#include <SPI.h>
#include <Adafruit_GFX.h>
#include <TFT_eSPI.h>

#define PIN_SCK  14
#define PIN_MOSI 13
#define PIN_MISO 12
#define PIN_CS   15
#define PIN_DC    2
#define PIN_BL   21

class ILI : public Adafruit_GFX {
  void cmd(uint8_t c) { digitalWrite(PIN_DC, LOW);  digitalWrite(PIN_CS, LOW); SPI.transfer(c); digitalWrite(PIN_CS, HIGH); }
  void dat(uint8_t d) { digitalWrite(PIN_DC, HIGH); digitalWrite(PIN_CS, LOW); SPI.transfer(d); digitalWrite(PIN_CS, HIGH); }
public:
  ILI() : Adafruit_GFX(240, 320) {}

  void begin() {
    pinMode(PIN_DC, OUTPUT);
    pinMode(PIN_CS, OUTPUT);
    pinMode(PIN_BL, OUTPUT);
    digitalWrite(PIN_CS, HIGH);
    digitalWrite(PIN_BL, HIGH);

    SPI.begin(PIN_SCK, PIN_MISO, PIN_MOSI, PIN_CS);
    SPI.beginTransaction(SPISettings(20000000, MSBFIRST, SPI_MODE0));

    cmd(0x01); delay(120);
    cmd(0x28);
    cmd(0xCF); dat(0x00); dat(0xC1); dat(0x30);
    cmd(0xED); dat(0x64); dat(0x03); dat(0x12); dat(0x81);
    cmd(0xE8); dat(0x85); dat(0x00); dat(0x78);
    cmd(0xCB); dat(0x39); dat(0x2C); dat(0x00); dat(0x34); dat(0x02);
    cmd(0xF7); dat(0x20);
    cmd(0xEA); dat(0x00); dat(0x00);
    cmd(0xC0); dat(0x23);
    cmd(0xC1); dat(0x10);
    cmd(0xC5); dat(0x3E); dat(0x28);
    cmd(0xC7); dat(0x86);
    cmd(0x36); dat(0x28);
    cmd(0x3A); dat(0x55);
    cmd(0xB1); dat(0x00); dat(0x18);
    cmd(0xB6); dat(0x08); dat(0x82); dat(0x27);
    cmd(0xF2); dat(0x00);
    cmd(0x26); dat(0x01);
    cmd(0xE0); dat(0x0F); dat(0x31); dat(0x2B); dat(0x0C); dat(0x0E); dat(0x08); dat(0x4E); dat(0xF1);
               dat(0x37); dat(0x07); dat(0x10); dat(0x03); dat(0x0E); dat(0x09); dat(0x00);
    cmd(0xE1); dat(0x00); dat(0x0E); dat(0x14); dat(0x03); dat(0x11); dat(0x07); dat(0x31); dat(0xC1);
               dat(0x48); dat(0x08); dat(0x0F); dat(0x0C); dat(0x31); dat(0x36); dat(0x0F);
    cmd(0x11); delay(120);
    cmd(0x29);
    delay(20);

    // окно на весь экран
    cmd(0x2A); dat(0x00); dat(0x00); dat(0x00); dat(0xEF);
    cmd(0x2B); dat(0x00); dat(0x00); dat(0x01); dat(0x3F);
    cmd(0x2C);
  }

  void drawPixel(int16_t x, int16_t y, uint16_t color) override {
    if (x < 0 || y < 0 || x >= 240 || y >= 320) return;
    cmd(0x2A); dat(0x00); dat(x); dat(0x00); dat(x);
    cmd(0x2B); dat(0x00); dat(y); dat(0x00); dat(y);
    cmd(0x2C);
    digitalWrite(PIN_DC, HIGH); digitalWrite(PIN_CS, LOW);
    SPI.transfer16(color);
    digitalWrite(PIN_CS, HIGH);
  }

  void fill(uint16_t color) {
    cmd(0x2A); dat(0x00); dat(0x00); dat(0x00); dat(0xEF);
    cmd(0x2B); dat(0x00); dat(0x00); dat(0x01); dat(0x3F);
    cmd(0x2C);
    digitalWrite(PIN_DC, HIGH); digitalWrite(PIN_CS, LOW);
    for (uint32_t i = 0; i < 240UL * 320UL; i++) SPI.transfer16(color);
    digitalWrite(PIN_CS, HIGH);
  }
};

ILI tft;

void setup() {
  Serial.begin(115200);
  delay(300);
  Serial.println("start");

  tft.begin();
  Serial.println("init done");

  tft.fill(0xFFFF); Serial.println("white"); delay(800);
  tft.fill(0xF800); Serial.println("red");   delay(800);
  tft.fill(0x07E0); Serial.println("green"); delay(800);
  tft.fill(0x001F); Serial.println("blue");  delay(800);
  tft.fill(0x0000);

  tft.setCursor(20, 40);
  tft.setTextColor(0xFFFF);
  tft.setTextSize(3);
  tft.println("DISPLAY OK");

  Serial.println("done");
}

void loop() {}
